CREATE OR REPLACE FUNCTION f_next_free_date(
    _input_date date
)
RETURNS date
LANGUAGE plpgsql STABLE STRICT
AS $func$
DECLARE
    _candidate date := _input_date;
BEGIN
    LOOP
        IF NOT EXISTS (
            SELECT 1
              FROM races
             WHERE date = _candidate
        )
        THEN
            RETURN _candidate;
        END IF;

        _candidate := _candidate + INTERVAL '1 day';
    END LOOP;
END;
