LANGUAGE plpgsql
AS $$
DECLARE
    i INT := 1;
    start_val INT := 120;
    counter_val INT := 1;
    end_val INT := 300;
BEGIN
    WHILE (i <= end_val) LOOP
        INSERT INTO table1 (start, counter, difference, "end")
        VALUES (start_val, counter_val, start_val + counter_val, end_val);
        i := i + 1;
        counter_val := counter_val + 1;
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE insertmore()
LANGUAGE plpgsql
AS $$
DECLARE
    start_val INT;
    counter_val INT := 1;
    end_val INT;
BEGIN
    SELECT COUNT(*) INTO end_val FROM table1;
    SELECT COALESCE(max(id) + 1, 1) INTO start_val FROM table1;

    WHILE (counter_val <= end_val) LOOP
        INSERT INTO table1 (start, counter, difference, "end")
        VALUES (start_val, counter_val, start_val + counter_val, end_val);
        counter_val := counter_val + 1;
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE FillCalendar()
LANGUAGE plpgsql
AS $$
DECLARE
    current_dt DATE;
BEGIN
    -- Initialize variables
    current_dt := '2010-01-01';

    -- In PostgreSQL, we don't need explicit transaction control in procedures
    -- as they automatically run in a transaction

    WHILE current_dt <= DATE '2014-12-31' LOOP
        -- Check if the current date is a weekend or holiday
        IF (EXTRACT(DOW FROM current_dt) = 0 OR EXTRACT(DOW FROM current_dt) = 6) OR current_dt IN (
            '2010-01-01', '2010-07-04', '2010-11-11', '2010-12-25',
            '2011-01-01', '2011-07-04', '2011-11-11', '2011-12-25',
            '2012-01-01', '2012-07-04', '2012-11-11', '2012-12-25',
            '2013-01-01', '2013-07-04', '2013-11-11', '2013-12-25',
            '2014-01-01', '2014-07-04', '2014-11-11', '2014-12-25'
        ) THEN
            INSERT INTO calendar (calendar_date) VALUES (current_dt);
        END IF;

        -- Move to the next day
        current_dt := current_dt + INTERVAL '1 day';
    END LOOP;
END;
$$;

